# -*- coding: utf-8 -*-
# Histoires du soir — histoires 41 à 60
HISTOIRES = [
 {"id": "h041", "age": "4-6", "titre": "Le petit lamantin de Conkouati",
  "texte": "Dans la lagune de Conkouati-Douli, près de l’océan, vivait un bébé lamantin. Les lamantins sont de grands animaux doux qui mangent des plantes d’eau. Le petit lamantin n’osait pas plonger tout seul. « Et si je me perdais ? » disait-il. Sa maman le poussa gentiment du museau : « Essaie un petit peu. Je suis juste à côté. » Il plongea la tête, puis le corps. L’eau était tiède et douce. Il trouva des herbes tendres et les mangea. Puis il remonta respirer à la surface, car les lamantins respirent de l’air. « J’ai réussi ! » Super Brazza, sur la rive, applaudit. Le courage, c’est essayer, même quand on a un peu peur. Bonne nuit, petit lamantin.",
  "morale": "Le courage, c’est essayer même quand on a un peu peur."},
 {"id": "h042", "age": "4-6", "titre": "Le mandrill aux mille couleurs",
  "texte": "Dans la forêt de la côte vivait un mandrill au visage tout coloré : rouge, bleu, jaune. Il était très fier. « Je suis le plus beau, disait-il, et le plus important. » Il ne parlait plus aux autres animaux. Un jour, il se perdit dans la brume. Il appela, mais personne ne répondit, parce qu’il avait été trop fier. Super Brazza l’entendit pourtant. « Je suis là, mandrill. » Il le ramena en le tenant par la main. Le mandrill baissa les yeux. « Pardon d’avoir été si fier. » Il comprit que les couleurs du visage sont jolies, mais que les amis valent plus que toutes les couleurs. Bonne nuit.",
  "morale": "Les amis valent plus que toutes les couleurs."},
 {"id": "h043", "age": "4-6", "titre": "Mama Nzoku et l’arc-en-ciel",
  "texte": "Après une grande pluie, le ciel du Congo était tout brillant. Mama Nzoku et Super Brazza virent un arc-en-ciel au-dessus de la forêt. « Oh ! Qui l’a peint ? » demanda Super Brazza. Mama Nzoku lui expliqua : « C’est le soleil qui traverse les gouttes de pluie. La lumière se partage en plusieurs couleurs : rouge, orange, jaune, vert, bleu, violet. » Super Brazza compta les couleurs sur ses doigts. Il remarqua que le drapeau du Congo en avait trois, le vert, le jaune et le rouge, comme un petit morceau d’arc-en-ciel. Ils restèrent longtemps à regarder. Parfois, après la pluie, la nature nous offre un cadeau. Bonne nuit.",
  "morale": "Après la pluie, la nature offre de beaux cadeaux."},
 {"id": "h044", "age": "4-6", "titre": "Les dents de Nkosi",
  "texte": "Nkosi le lion avait une très belle crinière, mais il refusait de se brosser les dents. « C’est ennuyeux ! » grognait-il. Un matin, il eut très mal à une dent. « Aïe, aïe, aïe ! » Super Brazza lui dit : « Les dents ont besoin de soins, comme tout le reste. Chaque matin et chaque soir, il faut les brosser doucement. » Nkosi apprit à se brosser : en haut, en bas, devant, derrière, pendant deux minutes. Il rit : « Ça chatouille ! » Quelques jours plus tard, il n’avait plus mal. Son sourire était blanc et brillant. Prendre soin de ses dents, c’est prendre soin de son sourire. Bonne nuit, avec les dents propres.",
  "morale": "Prendre soin de ses dents, c’est prendre soin de son sourire."},
 {"id": "h045", "age": "4-6", "titre": "La chikwangue de grand-mère",
  "texte": "Chez grand-mère, il y avait toujours de la chikwangue, une pâte de manioc cuite à la vapeur dans des feuilles. Super Brazza défit le paquet : il sentait bon, il était tout chaud. « C’est quoi, ces feuilles ? » demanda-t-il. « Elles gardent la chikwangue fraîche et lui donnent son parfum », répondit grand-mère. Super Brazza goûta, avec de la sauce. Il aima beaucoup. Il remercia grand-mère : « Matondi pour ce repas. » Elle sourit. « Un repas partagé fait toujours plaisir. » Super Brazza lui servit son assiette à elle aussi. Remercier celui qui prépare le repas, c’est une belle façon de dire je t’aime. Bonne nuit.",
  "morale": "Remercier celui qui prépare le repas, c’est dire je t’aime."},
 {"id": "h046", "age": "4-6", "titre": "Mokomboso apprend à perdre",
  "texte": "Pour la première fois, le petit chimpanzé Mokomboso perdit une course. Il tapa du pied. « Ce n’est pas juste ! » cria-t-il. Super Brazza s’approcha. « Tu as bien couru. Mais celui qui gagne aujourd’hui peut perdre demain. » Mokomboso renifla. « Je n’aime pas perdre. » Super Brazza sourit : « Moi non plus. Mais quand je perds, je félicite le gagnant, puis je m’entraîne. » Le chimpanzé serra la main de son ami vainqueur : « Bravo ! » Le lendemain, il s’entraîna, et il fit un meilleur temps. Savoir perdre, c’est apprendre à devenir meilleur. Bonne nuit, petit coureur.",
  "morale": "Savoir perdre, c’est apprendre à devenir meilleur."},
 {"id": "h047", "age": "7-9", "titre": "Le roi de Mbé",
  "texte": "Il y a très longtemps, à Mbé, un village à une centaine de kilomètres au nord de Brazzaville, vivait un grand roi, le Makoko, roi des Tékés. Un jour, un voyageur arriva : l’explorateur Pierre Savorgnan de Brazza. On raconte que le Makoko l’accueillit avec respect, comme on reçoit un invité, et qu’il prit le temps d’écouter et de réfléchir. Super Brazza, qui racontait cette histoire à ses amis, ajouta : « Accueillir un étranger, c’est beau. Prendre le temps de réfléchir avant de décider, c’est sage. » Ses amis hochèrent la tête. C’est une bonne leçon pour tous : on accueille bien, et on réfléchit avant de choisir. Bonne nuit.",
  "morale": "On accueille avec respect, et on réfléchit avant de décider."},
 {"id": "h048", "age": "7-9", "titre": "Le tour de Brazzaville",
  "texte": "Super Brazza fit le tour de Brazzaville avec sa cousine Grâce. Ils virent d’abord la basilique Sainte-Anne, avec son toit de tuiles vertes. « C’est la plus belle ! » dit Grâce. Puis la tour Nabemba, la plus haute de la ville. Super Brazza leva la tête : « Elle touche presque les nuages ! » Ensuite, ils passèrent près du pont du 15 août 1960, qui rappelle le jour de l’indépendance. Enfin, ils s’arrêtèrent devant le phare de Brazzaville. « Chaque monument raconte une histoire », dit Super Brazza. Grâce nota tout dans son carnet. Le soir, ils s’endormirent la tête pleine d’images. Connaître son pays, c’est l’aimer davantage. Bonne nuit.",
  "morale": "Connaître son pays, c’est l’aimer davantage."},
 {"id": "h049", "age": "7-9", "titre": "Le grand concert du FESPAM",
  "texte": "Cette année, le FESPAM, le grand festival de musique africaine, avait lieu à Brazzaville. Kévin et Super Brazza se faufilèrent dans la foule. Il y avait des musiciens de tous les pays : des chanteurs, des joueurs de tambour, des danseurs. On entendait des langues différentes, mais la musique, elle, parlait à tout le monde. Kévin tapait du pied sans même s’en rendre compte. Une chanteuse l’invita à danser. Il hésita, puis il sauta sur la piste. « Dansons ! » cria Super Brazza. Quand la nuit tomba, Kévin comprit que la musique est un pont entre les gens. Bonne nuit, petit danseur.",
  "morale": "La musique est un pont entre les gens."},
 {"id": "h050", "age": "7-9", "titre": "L’orchestre de Brazzaville",
  "texte": "Il y a longtemps, à Brazzaville, naissait un orchestre célèbre, Les Bantous de la Capitale, le 15 août 1959. Super Brazza imagina comment les musiciens répétaient. Il y avait des guitaristes, des chanteurs, des joueurs de saxophone et de tambour. Au début, chacun jouait pour lui-même, et cela faisait un grand bruit. Alors, imagina Super Brazza, le chef leur dit : « Écoutez-vous. Aucun instrument n’est plus important que les autres. » Ils jouèrent ensemble, doucement, chacun à son tour, puis tous ensemble. Le public se leva pour danser. Super Brazza comprit : une équipe, c’est comme un orchestre. Chacun joue sa partie, et ensemble, cela donne de la magie. Bonne nuit.",
  "morale": "Dans une équipe, chacun joue sa partie, et ensemble c’est magique."},
 {"id": "h051", "age": "7-9", "titre": "La légende du lac Télé",
  "texte": "Au nord du Congo, dans la Likouala, il y a un lac entouré de forêts inondées : le lac Télé. Une vieille légende dit qu’un animal gigantesque, le Mokélé-mbembé, y vivrait. Super Brazza et Prince écoutaient le conteur, les yeux écarquillés. « Est-ce que c’est vrai ? » demanda Prince. Le conteur sourit : « Personne n’a jamais prouvé qu’il existe. C’est une légende. Mais les légendes font rêver, et elles nous apprennent à respecter la forêt. » Prince hésita. Super Brazza dit : « On peut aimer une histoire sans oublier la vérité. » Cette nuit-là, ils rêvèrent d’un grand lac plein de mystères. Bonne nuit.",
  "morale": "On peut aimer une légende sans oublier la vérité."},
 {"id": "h052", "age": "7-9", "titre": "La lumière du barrage",
  "texte": "À l’école du village, la lumière s’éteignait souvent. Un soir, Super Brazza apprit une bonne nouvelle : un grand barrage, celui d’Imboulou, produisait de l’électricité grâce à la force de l’eau. « L’eau fait tourner de grandes machines, expliqua l’ingénieur. Elles fabriquent du courant. » Grâce regarda la lampe qui brillait. « Alors c’est l’eau qui nous éclaire ! » L’ingénieur sourit : « Oui, mais il ne faut pas la gaspiller. Éteignez la lumière quand vous n’en avez pas besoin. » Super Brazza s’en souvint. Chaque soir, il éteignait les lampes inutiles. Économiser l’énergie, c’est aider la planète. Bonne nuit.",
  "morale": "Économiser l’énergie, c’est aider la planète."},
 {"id": "h053", "age": "7-9", "titre": "Le sanctuaire des petits chimpanzés",
  "texte": "Près de Pointe-Noire, il y a un sanctuaire où vivent des chimpanzés orphelins. Super Brazza leur rendit visite avec un soigneur. Un petit chimpanzé, très craintif, se cachait dans un coin. « Il a eu une vie difficile, expliqua le soigneur. Il faut du temps pour qu’il fasse confiance. » Super Brazza s’assit tranquillement, sans bouger. Le petit chimpanzé s’approcha, puis il lui toucha la main. « Tu vois, dit le soigneur, la gentillesse parle plus fort que les mots. » Super Brazza sourit. Ce soir-là, il pensa à tous ceux qui ont besoin d’être aimés. Bonne nuit.",
  "morale": "La gentillesse parle plus fort que les mots."},
 {"id": "h054", "age": "7-9", "titre": "Les premiers pas de Moko",
  "texte": "Dans la réserve de Lésio-Louna, au nord de Brazzaville, de jeunes gorilles orphelins apprennent à vivre dans la nature. Ils grimpent aux arbres, cherchent des feuilles et des fruits. Un petit gorille, Moko, hésitait à s’éloigner de son soigneur. « Et si je me trompe ? » Le soigneur lui dit : « Essaie, je suis là. » Moko fit quelques pas, trouva un fruit, puis un autre. Il revint, tout fier. Peu à peu, il alla plus loin, et un jour, il vécut librement. Super Brazza observait de loin. Grandir, c’est oser faire ses premiers pas, un peu plus loin chaque jour. Bonne nuit.",
  "morale": "Grandir, c’est oser aller un peu plus loin chaque jour."},
 {"id": "h055", "age": "7-9", "titre": "La chute de la Loufoulakari",
  "texte": "Un week-end, Super Brazza partit avec ses cousins voir la chute de la Loufoulakari. Le chemin était long, et les plus petits se plaignaient : « On est fatigués ! » Super Brazza leur dit : « Chantons pour marcher plus vite ! » Ils chantèrent, ils rirent, ils s’entraidèrent pour traverser un petit ruisseau. Quand ils arrivèrent, l’eau tombait avec un grand bruit, en nuages de gouttelettes. « Waouh ! » crièrent les cousins. Tous se tenaient par la main, émerveillés. « On n’aurait rien vu si on s’était arrêtés », dit le plus petit. Les belles choses se méritent. Bonne nuit.",
  "morale": "Les belles choses se méritent."},
 {"id": "h056", "age": "10-12", "titre": "Le pétrole et la mer",
  "texte": "Au bord de l’océan, près de Pointe-Noire, Moïse rencontra une ingénieure qui travaillait dans le pétrole, une grande richesse du pays. « Le pétrole vient de la mer, expliqua-t-elle. Il aide le Congo, mais il faut le manipuler avec soin. » Moïse, dont le grand-père était pêcheur, s’inquiéta : « Et si le pétrole salit l’eau ? Les poissons mourraient. » L’ingénieure hocha la tête : « Tu as raison de poser cette question. C’est pour cela qu’il faut des règles très strictes, et des méthodes plus propres. » Moïse décida d’étudier, pour devenir lui aussi quelqu’un qui protège la mer. Super Brazza l’encouragea. Le progrès, c’est avancer sans abîmer la nature. Bonne nuit.",
  "morale": "Le progrès, c’est avancer sans abîmer la nature."},
 {"id": "h057", "age": "10-12", "titre": "L’or vert de Dolisie",
  "texte": "À Dolisie, que l’on surnomme la capitale de l’or vert à cause du bois, vivait Papa Tobie, un ancien bûcheron. Il racontait à Super Brazza : « Quand j’étais jeune, on coupait les arbres sans réfléchir. Aujourd’hui, je sais que pour chaque arbre coupé, il faut en replanter. » Il montra une petite pépinière où poussaient de jeunes plants. « Ce sont les forêts de tes enfants. » Super Brazza prit un petit arbre dans ses mains. « Je vais l’arroser tous les jours. » Le vieil homme sourit. L’or vert n’est pas fait pour être épuisé, mais pour être soigné. Bonne nuit.",
  "morale": "La forêt n’est pas faite pour être épuisée, mais soignée."},
 {"id": "h058", "age": "10-12", "titre": "La carte du Congo",
  "texte": "Grâce dessina une grande carte du Congo avec Super Brazza. Au sud, Brazzaville, au bord du fleuve. Au sud-ouest, Pointe-Noire, au bord de l’océan Atlantique. À l’ouest, le Gabon. Au nord-ouest, le Cameroun. Au nord, la Centrafrique. À l’est, de l’autre côté du fleuve, la République démocratique du Congo. Et tout au sud, près de la côte, le Cabinda, qui appartient à l’Angola. « Cinq voisins ! » compta Grâce. Elle colora chaque pays d’une couleur différente, puis ajouta le drapeau du Congo : vert, jaune, rouge. « Je connais mon pays maintenant, dit-elle. Et ses voisins. » Connaître sa carte, c’est connaître sa maison. Bonne nuit.",
  "morale": "Connaître sa carte, c’est connaître sa maison."},
 {"id": "h059", "age": "10-12", "titre": "Les deux langues",
  "texte": "Prince vivait à Brazzaville et sa cousine Grâce à Pointe-Noire. Au téléphone, ils se saluaient chacun dans leur langue. À Brazzaville, on parle surtout le lingala : « Mbote ! » À Pointe-Noire, on parle surtout le kituba, qu’on appelle aussi munukutuba. Prince voulait apprendre le kituba, et Grâce le lingala. Super Brazza leur dit : « Une langue de plus, c’est une porte de plus pour entrer dans le cœur des autres. » Ils s’apprirent des mots, au téléphone puis pendant les vacances. À la fin de l’été, ils pouvaient parler dans les deux langues. Avoir plusieurs langues, c’est avoir plusieurs richesses. Bonne nuit.",
  "morale": "Avoir plusieurs langues, c’est avoir plusieurs richesses."},
 {"id": "h060", "age": "4-6", "titre": "Merci pour cette journée",
  "texte": "Avant de dormir, Super Brazza s’allongea sur son lit de feuilles. Il repensa à sa journée. « Matondi pour le soleil du matin. Matondi pour la mangue que j’ai partagée. Matondi pour mes amis, Papa Gorille, Nkoyi, Nkosi et Mama Nzoku. Matondi pour la maison, ndako, où je dors. » Il sourit. Un petit vent doux caressait les feuilles. La lune brillait sur le fleuve. Super Brazza ferma les yeux, le cœur plein de merci. Dis toi aussi, dans ta tête, un grand merci pour ta journée. Puis ferme les yeux, et dors bien, petit champion. Bonne nuit.",
  "morale": "Dire merci avant de dormir rend le cœur léger."},
]
